"use client";

// Shared data store: demo data (generated by the real CIE engine) or the
// user's own exported files. Zustand keeps it simple — no backend needed.
//
// The workspace layout (inspired by a code-intelligence UI) has three zones:
//   topbar  — model picker + repo chip + main menus
//   stage   — the chart engine in the middle (map, charts, story pages)
//   chat    — Ask CIE on the right, wired to the stage
// so the store also carries which view the stage shows, any chart the chat
// asked it to render big, and the map bubble the user picked (which the chat
// offers as a referent).

import { create } from "zustand";
import type { CieReport, CieViewSpec, ConceptTree, VizElement, CieDeps, CieRuntime, CieStories, CieQuality } from "./cie-types";
import type { ChatChartSpec } from "./chat-chart";
import type { RepoScan } from "./language-profiles";
import { DEFAULT_LLM, loadLlmConfig, saveLlmConfig, type LlmConfig } from "./llm-config";

export type DataSource = "demo" | "custom" | null;

// Every page the middle stage can show. "chart" renders a chart the chat
// (or a menu tap) sent to the canvas.
export type StageView =
  | "start"
  | "map"
  | "does"
  | "fixes"
  | "promises"
  | "numbers"
  | "menu"
  | "trust"
  | "deps"
  | "runtime"
  | "quality"
  | "chart";

// One bubble in the "Ask CIE" conversation. `chart` is the complementary
// chart the AI attached to its answer (US-020 catalog pick), if any. Failed
// sends carry `technical` (collapsible) and `providerIssue` (offer to open
// the connection settings). `instant` marks answers drawn locally from the
// loaded store (draw-anything.ts) — no AI was involved, and the footer says
// so instead of naming a provider.
export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  error?: boolean;
  chart?: ChatChartSpec;
  technical?: string;
  providerIssue?: boolean;
  instant?: boolean;
}

/**
 * "Show me the code" — a chart element with a known source location opened
 * the source panel. Carries everything the panel needs: where to look, which
 * byte offsets/line to highlight, and which chart element asked (so the
 * panel's "Ask CIE about this" button can hand a grounded question to chat).
 */
export interface SourceViewerRequest {
  file: string; // repo-relative path, exactly as the exports name it
  line?: number; // flat real line number when the export carried one
  endLine?: number;
  byteStart?: number; // report.json symbols[].loc — resolved to a line
  byteEnd?: number; // only when the file's content is available
  elName?: string;
  elValue?: number | string;
  chartTitle?: string;
}

interface CieState {
  report: CieReport | null;
  viewspec: CieViewSpec | null;
  concepts: ConceptTree | null;
  deps: CieDeps | null; // dependency manifests (cie deps export) — null when none
  runtime: CieRuntime | null; // collected runtime evidence — null when the project has none
  stories: CieStories | null; // the 33 story demos with real data — null when the project has none
  quality: CieQuality | null; // health/quality ETL export — null when the project has none
  source: DataSource;
  label: string;
  loading: boolean;
  loadError: string;
  chat: ChatMessage[];
  chatBusy: boolean;
  jobId: string | null; // active "Connect a repo" job, survives dialog close
  repoScan: RepoScan | null; // language inventory from connect-a-repo flows

  // workspace state
  view: StageView; // what the middle stage shows
  canvasChart: ChatChartSpec | null; // the chart sent to the canvas (view === "chart")
  mapSelected: VizElement | null; // map bubble picked; the chat offers it as a referent
  llm: LlmConfig; // who answers — hydrated from localStorage after mount
  llmSettingsOpen: boolean; // the connection settings dialog (topbar owns it)
  pendingAsk: string | null; // click-to-chat: a question any chart/card handed to the chat

  // source panel — click a chart element with a location, see the code
  sourceViewer: SourceViewerRequest | null;
  sourceRoot: string | null; // absolute root of a consented local-folder project (URL clones are deleted after analysis — null there, honestly)
  sourceCache: Record<string, string>; // fetched file contents, by repo-relative path

  loadDemo: () => Promise<void>;
  setCustom: (
    report: CieReport | null,
    viewspec: CieViewSpec | null,
    concepts: ConceptTree | null,
    label: string,
    repoScan?: RepoScan | null,
    deps?: CieDeps | null,
    runtime?: CieRuntime | null,
    stories?: CieStories | null,
    quality?: CieQuality | null,
    sourceRoot?: string | null
  ) => void;
  reset: () => void;
  pushChat: (m: ChatMessage) => void;
  setChatBusy: (b: boolean) => void;
  clearChat: () => void;
  setJobId: (id: string | null) => void;
  setView: (v: StageView) => void;
  openChartOnCanvas: (spec: ChatChartSpec) => void;
  closeCanvasChart: () => void;
  setMapSelected: (el: VizElement | null) => void;
  setPendingAsk: (q: string | null) => void;
  setLlm: (cfg: LlmConfig) => void;
  hydrateLlm: () => void;
  setLlmSettingsOpen: (open: boolean) => void;
  openSourceViewer: (req: SourceViewerRequest) => void;
  closeSourceViewer: () => void;
  cacheSource: (path: string, content: string) => void;
}

export const useCie = create<CieState>((set, get) => ({
  report: null,
  viewspec: null,
  concepts: null,
  deps: null,
  runtime: null,
  stories: null,
  quality: null,
  source: null,
  label: "",
  loading: true,
  loadError: "",
  chat: [],
  chatBusy: false,
  jobId: null,
  repoScan: null,
  view: "start",
  canvasChart: null,
  mapSelected: null,
  llm: DEFAULT_LLM,
  llmSettingsOpen: false,
  pendingAsk: null,
  sourceViewer: null,
  sourceRoot: null,
  sourceCache: {},

  loadDemo: async () => {
    set({ loading: true, loadError: "" });
    try {
      // deps.json + runtime.json + stories.json are optional extras: a project
      // without them still loads, and those views show honest empty states.
      const [report, viewspec, concepts, deps, runtime, stories, quality] = await Promise.all([
        fetch("/data/report.json").then((r) => r.json()),
        fetch("/data/viewspec.json").then((r) => r.json()),
        fetch("/data/concepts.json").then((r) => r.json()),
        fetch("/data/deps.json").then((r) => r.json()).catch(() => null),
        fetch("/data/runtime.json").then((r) => r.json()).catch(() => null),
        fetch("/data/stories.json").then((r) => r.json()).catch(() => null),
        fetch("/data/quality.json").then((r) => r.json()).catch(() => null),
      ]);
      set({
        report,
        viewspec,
        concepts,
        deps,
        runtime,
        stories,
        quality,
        source: "demo",
        label: "Sample project: a small banking app (13 files — Python, SQL and shell)",
        loading: false,
        chat: [],
        chatBusy: false,
        repoScan: null,
        view: "start",
        canvasChart: null,
        mapSelected: null,
      });
    } catch {
      set({ loading: false, loadError: "Could not load the sample data. Please refresh the page." });
    }
  },

  setCustom: (report, viewspec, concepts, label, repoScan, deps, runtime, stories, quality, sourceRoot) =>
    set({
      report,
      viewspec,
      concepts,
      deps: deps ?? null,
      runtime: runtime ?? null,
      stories: stories ?? null,
      quality: quality ?? null,
      source: "custom",
      label,
      loading: false,
      loadError: "",
      chat: [],
      chatBusy: false,
      // The scan only exists for connect-a-repo flows; switching to the
      // sample or to uploaded files honestly drops it.
      repoScan: repoScan ?? null,
      // Only local-folder projects keep a readable root on this machine.
      // URL clones are deleted after analysis and uploads never touched
      // disk — the source panel says so honestly for those.
      sourceRoot: sourceRoot ?? null,
      sourceCache: {},
      sourceViewer: null,
      // A new project starts on its own front page, not on an old chart.
      view: get().view === "chart" ? "start" : get().view,
      canvasChart: null,
      mapSelected: null,
    }),

  reset: () => {
    void useCie.getState().loadDemo();
  },

  pushChat: (m) => set((s) => ({ chat: [...s.chat, m] })),
  setChatBusy: (b) => set({ chatBusy: b }),
  clearChat: () => set({ chat: [] }),
  setJobId: (id) => set({ jobId: id }),

  setView: (v) => set({ view: v }),

  openChartOnCanvas: (spec) => set({ canvasChart: spec, view: "chart" }),
  closeCanvasChart: () => set({ canvasChart: null, view: "start" }),

  setMapSelected: (el) => set({ mapSelected: el }),

  setPendingAsk: (q) => set({ pendingAsk: q }),

  setLlm: (cfg) => {
    saveLlmConfig(cfg);
    set({ llm: cfg });
  },

  // Called once after mount (localStorage is browser-only).
  hydrateLlm: () => set({ llm: loadLlmConfig() }),

  setLlmSettingsOpen: (open) => set({ llmSettingsOpen: open }),

  openSourceViewer: (req) => set({ sourceViewer: req }),
  closeSourceViewer: () => set({ sourceViewer: null }),
  cacheSource: (path, content) => set((s) => ({ sourceCache: { ...s.sourceCache, [path]: content } })),
}));
